                let timesAdd = 1
                if (hasMilestone("l", 1)) timesAdd *= 3
                if (player.easyMode) timesAdd *= 2
                player.p.times += timesAdd
                player.p.currentGainPerSec = player.p.currentGainPerSec.plus(gain)
