                                let coinUpgRem = [11, 21, 22, 31, 32, 
                                                  33, 34, 41, 42, 51, 
                                                  52, 61, 62, 71, 72, 
                                                  73, 81, 82, 91, 92, 
                                                  93, 94, 95]
                                // upgrades
