                                if (hasMilestone("d", 6)) lb = "log8"
                                if (hasMilestone("d", 7)) lb = "log7"
                                if (hasMilestone("d", 8)) lb = "log6"
                                if (hasMilestone("d", 9)) lb = "log5"
                                if (hasMilestone("d", 10)) lb = "log4"
